@Configuration
@EnableWebSecurity       // activates SecurityFilterChain, URL-based security
@EnableMethodSecurity    // activates @PreAuthorize, @PostAuthorize, @Secured
public class SecurityConfig {

    @Bean
    public SecurityFilterChain chain(HttpSecurity http) throws Exception {
        // URL-based rules (requires @EnableWebSecurity)
        http.authorizeHttpRequests(auth -> auth
            .requestMatchers("/admin/**").hasRole("ADMIN")
            .anyRequest().authenticated()
        );
        return http.build();
    }
}

@Service
public class UserService {
    @PreAuthorize("hasRole('ADMIN')")  // requires @EnableMethodSecurity
    public void deleteUser(Long id) { ... }
}
